import sys, json, re


class Skip(Exception):
    pass


REAL = set("""Other Application Group Window Sheet Drawer Alert Dialog Button RadioButton RadioGroup CheckBox
DisclosureTriangle PopUpButton ComboBox MenuButton ToolbarButton Popover Keyboard Key NavigationBar TabBar TabGroup
Toolbar StatusBar Table TableRow TableColumn Outline OutlineRow Browser CollectionView Slider PageIndicator
ProgressIndicator ActivityIndicator SegmentedControl Picker PickerWheel Switch Toggle Link Image Icon SearchField
ScrollView ScrollBar StaticText TextField SecureTextField DatePicker TextView Menu MenuItem MenuBar MenuBarItem Map
WebView IncrementArrow DecrementArrow Timeline RatingIndicator ValueIndicator SplitGroup Splitter RelevanceIndicator
ColorWell HelpTag Matte DockItem Ruler RulerMarker Grid LevelIndicator Cell LayoutArea LayoutItem Handle Stepper Tab
TouchBar StatusItem""".split())
PREFIX = {"Key", "Menu", "MenuBar", "Outline", "Picker", "Ruler", "Tab", "Table", "Toolbar"}
P = "XCUIElementType"

TEXT = {"name", "label", "value", "placeholderValue"}
BOOL = {"enabled", "visible", "accessible", "hittable"}
NUM = {"index": "index", "x": "rect.x", "y": "rect.y", "width": "rect.width", "height": "rect.height"}
ATTRS = TEXT | BOOL | set(NUM) | {"type"}


def real_type(s):
    if s.startswith(P) and s[len(P):] in REAL:
        return s
    return None


TOK = re.compile(r'''\s*(?:
 (?P<str>"(?:[^"]|"")*"|'(?:[^']|'')*')|
 (?P<num>\d+(?:\.\d+)?|\.\d+)|
 (?P<name>[A-Za-z_][\w\-\.]*)|
 (?P<op>//|::|\.\.|!=|<=|>=|[/@()\[\],|=<>*.\-+])
)''', re.X)


def tokenize(s):
    pos = 0
    out = []
    while True:
        if s[pos:].strip() == "":
            break
        m = TOK.match(s, pos)
        if not m:
            raise Skip("unparseable XPath")
        pos = m.end()
        k = m.lastgroup
        v = m.group(k)
        if k == "str":
            q = v[0]
            v = v[1:-1].replace(q + q, q)
        out.append((k, v))
    return out


class Parser:
    def __init__(self, toks):
        self.t = toks
        self.i = 0

    def peek(self, n=0):
        j = self.i + n
        return self.t[j] if j < len(self.t) else (None, None)

    def next(self):
        r = self.peek()
        self.i += 1
        return r

    def isop(self, v, n=0):
        return self.peek(n) == ("op", v)

    def expect(self, v):
        if not self.isop(v):
            raise Skip("unparseable XPath")
        self.i += 1

    def end(self):
        if self.i != len(self.t):
            raise Skip("unsupported XPath construct")

    def parse_top(self):
        if self.isop("("):
            self.i += 1
            paths = self.parse_union()
            self.expect(")")
            idx = None
            if self.isop("["):
                self.i += 1
                idx = self.parse_expr()
                self.expect("]")
            self.end()
            return ("wrap", paths, idx)
        paths = self.parse_union()
        self.end()
        return ("wrap", paths, None) if False else ("paths", paths)

    def parse_union(self):
        paths = [self.parse_path()]
        while self.isop("|"):
            self.i += 1
            paths.append(self.parse_path())
        return paths

    def parse_path(self):
        start = None
        if self.isop(".") and (self.isop("/", 1) or self.isop("//", 1)):
            self.i += 1
            start = "."
        steps = []
        first = True
        while True:
            if first:
                if self.isop("/") or self.isop("//"):
                    sep = self.next()[1]
                    if start is None:
                        start = "abs"
                else:
                    sep = ""
                first = False
            steps.append(self.parse_step(sep))
            if self.isop("/") or self.isop("//"):
                sep = self.next()[1]
                continue
            break
        return {"start": start, "steps": steps}

    def parse_step(self, sep):
        axis = "child"
        if self.isop(".."):
            self.i += 1
            return {"sep": sep, "axis": "parent", "test": "..", "preds": self.parse_preds()}
        if self.isop("."):
            self.i += 1
            return {"sep": sep, "axis": "self", "test": ".", "preds": self.parse_preds()}
        k, v = self.peek()
        if k == "name" and self.isop("::", 1):
            axis = v
            self.i += 2
        k, v = self.next()
        if k == "name" or (k == "op" and v == "*"):
            test = v
        else:
            raise Skip("unparseable XPath")
        return {"sep": sep, "axis": axis, "test": test, "preds": self.parse_preds()}

    def parse_preds(self):
        preds = []
        while self.isop("["):
            self.i += 1
            preds.append(self.parse_expr())
            self.expect("]")
        return preds

    def parse_expr(self):
        items = [self.parse_and()]
        while self.peek() == ("name", "or"):
            self.i += 1
            items.append(self.parse_and())
        return items[0] if len(items) == 1 else ("or", items)

    def parse_and(self):
        items = [self.parse_cmp()]
        while self.peek() == ("name", "and"):
            self.i += 1
            items.append(self.parse_cmp())
        return items[0] if len(items) == 1 else ("and", items)

    def parse_cmp(self):
        l = self.parse_add()
        k, v = self.peek()
        if k == "op" and v in ("=", "!=", "<", "<=", ">", ">="):
            self.i += 1
            r = self.parse_add()
            return ("cmp", v, l, r)
        return l

    def parse_add(self):
        l = self.parse_primary()
        while self.peek()[0] == "op" and self.peek()[1] in ("+", "-"):
            op = self.next()[1]
            r = self.parse_primary()
            l = ("arith", op, l, r)
        return l

    def parse_primary(self):
        k, v = self.peek()
        if k == "str":
            self.i += 1
            return ("str", v)
        if k == "num":
            self.i += 1
            return ("num", v)
        if k == "op" and v == "@":
            self.i += 1
            k2, v2 = self.next()
            if k2 != "name":
                raise Skip("unsupported attribute wildcard")
            return ("attr", v2)
        if k == "op" and v == "(":
            self.i += 1
            e = self.parse_expr()
            self.expect(")")
            return e
        if k == "name" and self.isop("(", 1):
            self.i += 2
            args = []
            if not self.isop(")"):
                args.append(self.parse_expr())
                while self.isop(","):
                    self.i += 1
                    args.append(self.parse_expr())
            self.expect(")")
            return ("fn", v, args)
        if k == "op" and v == "." and not (self.isop("/", 1) or self.isop("//", 1)):
            self.i += 1
            return ("dot",)
        if (k == "name") or (k == "op" and v in (".", "/", "//", "*", "..")):
            return ("path", self.parse_path())
        raise Skip("unparseable XPath")


def q(s):
    out = []
    for ch in s:
        if ch == "\\":
            out.append("\\\\")
        elif ch == '"':
            out.append('\\"')
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\t":
            out.append("\\t")
        elif ch == "\r":
            out.append("\\r")
        elif ch == "`":
            out.append("``")
        elif ord(ch) < 32:
            raise Skip("control character in literal")
        else:
            out.append(ch)
    return '"' + "".join(out) + '"'


def strlit(n):
    if n[0] == "str":
        return n[1]
    if n[0] == "fn" and n[1] == "concat":
        parts = [strlit(a) for a in n[2]]
        if any(p is None for p in parts) or len(parts) < 2:
            return None
        return "".join(parts)
    return None


NSOPS = {"contains": "CONTAINS", "starts-with": "BEGINSWITH", "ends-with": "ENDSWITH"}
BADFN = {"normalize-space", "string-length", "replace", "tokenize", "string-join", "count", "text"}


def type_of(node):
    """Return real type name if node is a test on @type; None if not a type test."""
    if node[0] == "cmp":
        _, op, l, r = node
        for a, b in ((l, r), (r, l)):
            if a == ("attr", "type"):
                s = strlit(b)
                if op == "=" and s is not None and real_type(s):
                    return s
                raise Skip("unsupported test on @type")
        return None
    if node[0] == "fn" and node[1] in NSOPS | {"matches": 1}:
        args = node[2]
        if args and "type" in uses_attr(args[0]):
            if node[1] in NSOPS and len(args) == 2 and args[0] == ("attr", "type"):
                s = strlit(args[1])
                if s and real_type(s) and s[len(P):] not in PREFIX:
                    return s
            raise Skip("unsupported test on @type")
    return None


def uses_attr(n):
    if n[0] == "attr":
        return {n[1]}
    if n[0] == "fn":
        r = set()
        for a in n[2]:
            r |= uses_attr(a)
        return r
    return set()


def text_arg(n):
    """-> (attr, mode) mode in None/lower/upper"""
    if n[0] == "attr":
        return n[1], None
    if n[0] == "dot":
        raise Skip('"." used as text')
    if n[0] == "fn":
        f, args = n[1], n[2]
        if f in BADFN:
            raise Skip(f"{f}() has no exact class chain form")
        if f in ("lower-case", "upper-case") and len(args) == 1 and args[0][0] == "attr":
            return args[0][1], f.split("-")[0]
        if f == "translate" and len(args) == 3 and args[0][0] == "attr":
            a, b = strlit(args[1]), strlit(args[2])
            U = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
            if a == U and b == U.lower():
                return args[0][1], "lower!"
            if a == U.lower() and b == U:
                return args[0][1], "upper!"
            raise Skip("unsupported translate()")
        raise Skip(f"unsupported function {f}()")
    raise Skip("unsupported text expression")


def check_attr(a):
    if a not in ATTRS:
        raise Skip(f"attribute @{a} is not searchable in class chain")


def case_ok(mode, lit):
    if not lit or not lit.isascii():
        raise Skip("case-folded literal not ASCII/non-empty")
    if mode.startswith("lower") and lit != lit.lower():
        raise Skip("literal can never match lower-case()")
    if mode.startswith("upper") and lit != lit.upper():
        raise Skip("literal can never match upper-case()")


def is_true_drop(n):
    if n[0] == "cmp" and n[1] == "=":
        for a, b in ((n[2], n[3]), (n[3], n[2])):
            if a[0] == "attr" and b[0] == "fn" and b[1] in ("true", "false"):
                if a[1] in BOOL and b[1] == "true":
                    return True
                raise Skip("true()/false() usage not supported")
    return False


def rend_children(items, own):
    out = []
    for it in items:
        s, k = render(it)
        if own == "and" and k == "or":
            s = f"({s})"
        if own == "or" and k == "and":
            s = f"({s})"
        out.append(s)
    return out


def flatten(n, kind):
    if n[0] == kind:
        r = []
        for c in n[1]:
            r += flatten(c, kind)
        return r
    return [n]


def render(n):
    t = n[0]
    if t == "and":
        return " AND ".join(rend_children(flatten(n, "and"), "and")), "and"
    if t == "or":
        return " OR ".join(rend_children(flatten(n, "or"), "or")), "or"
    T = type_of(n)
    if T:
        return f'type == "{T}"', "atom"
    if t == "attr":
        a = n[1]
        check_attr(a)
        if a in TEXT | BOOL or a == "index":
            return f"{a} != nil", "atom"
        raise Skip("existence test not supported for this attribute")
    if t == "cmp":
        return render_cmp(n)
    if t == "fn":
        return render_fn(n)
    if t == "path":
        raise Skip("child/descendant test not supported here")
    if t == "num":
        raise Skip("positional predicate")
    if t == "dot":
        raise Skip('"." used as text')
    raise Skip("unsupported expression")


FLIP = {"=": "=", "!=": "!=", "<": ">", "<=": ">=", ">": "<", ">=": "<="}


def render_cmp(n):
    _, op, l, r = n
    if is_true_drop(n):
        raise Skip("true() not at top level")
    # normalise: put the attribute / function on the left
    if l[0] in ("str", "num") or (l[0] == "fn" and strlit(l) is not None):
        l, r, op = r, l, FLIP[op]
    if l[0] == "attr":
        a = l[1]
        check_attr(a)
        if a in TEXT:
            s = strlit(r)
            if s is None:
                raise Skip("comparison with non-string")
            if op == "=":
                return f"{a} == {q(s)}", "atom"
            if op == "!=":
                return f"{a} != nil AND {a} != {q(s)}", "and"
            raise Skip("< / > on a text attribute")
        if a in BOOL:
            s = strlit(r)
            if s in ("true", "false") and op in ("=", "!="):
                if op == "=":
                    return f"{a} == {s}", "atom"
                return f"{a} != nil AND {a} != {s}", "and"
            raise Skip("unsupported boolean attribute comparison")
        if a in NUM:
            if r[0] == "num":
                v = r[1]
            else:
                s = strlit(r)
                if s is None or not re.fullmatch(r"\d+(\.\d+)?", s):
                    raise Skip("non-numeric comparison on numeric attribute")
                if op in ("=", "!=") and not re.fullmatch(r"(0|[1-9]\d*)", s):
                    raise Skip("non-canonical number string")
                v = s
            o = "==" if op == "=" else op
            return f"{NUM[a]} {o} {v}", "atom"
        raise Skip("unsupported attribute comparison")
    if l[0] == "fn" and l[1] in ("lower-case", "upper-case"):
        a, mode = text_arg(l)
        s = strlit(r)
        if a in TEXT and op == "=" and s is not None:
            case_ok(mode, s)
            return f"{a} ==[c] {q(s)}", "atom"
        raise Skip("unsupported case comparison")
    if l[0] == "fn" and l[1] in BADFN:
        raise Skip(f"{l[1]}() has no exact class chain form")
    if l[0] == "fn" and l[1] == "translate":
        raise Skip("translate() equality not supported")
    if l[0] == "dot":
        raise Skip('"." used as text')
    raise Skip("unsupported comparison")


META = set("\\^$.|?*+()[]{}")


def render_fn(n):
    _, f, args = n
    if f == "not":
        if len(args) != 1:
            raise Skip("bad not()")
        if args[0][0] == "path":
            raise Skip("not() of a path")
        if is_true_drop(args[0]):
            raise Skip("true() not at top level")
        s, k = render(args[0])
        return f"NOT ({s})", "atom"
    if f in BADFN:
        raise Skip(f"{f}() has no exact class chain form")
    if f in NSOPS:
        if len(args) != 2:
            raise Skip("bad arguments")
        a, mode = text_arg(args[0])
        s = strlit(args[1])
        if s is None:
            raise Skip("non-literal argument")
        check_attr(a)
        if a in BOOL:
            if mode is None and s in ("true", "false"):
                return f"{a} == {s}", "atom"
            raise Skip("only true/false allowed on boolean attributes")
        if a not in TEXT:
            raise Skip("text function on non-text attribute")
        if s == "":
            raise Skip("empty literal")
        if mode:
            case_ok(mode, s)
            return f"{a} {NSOPS[f]}[c] {q(s)}", "atom"
        return f"{a} {NSOPS[f]} {q(s)}", "atom"
    if f == "matches":
        if len(args) not in (2, 3):
            raise Skip("bad matches()")
        if args[0][0] != "attr":
            raise Skip("matches() on non-attribute")
        a = args[0][1]
        check_attr(a)
        if a not in TEXT:
            raise Skip("matches() on non-text attribute")
        p = strlit(args[1])
        if p is None:
            raise Skip("non-literal pattern")
        flags = ""
        if len(args) == 3:
            flags = strlit(args[2])
            if flags is None or flags not in ("", "i"):
                raise Skip("regex flags other than i")
        if any(c.isspace() for c in p):
            raise Skip("pattern contains whitespace")
        if p == "":
            raise Skip("empty pattern")
        if not any(c in META for c in p):
            return f"{a} CONTAINS{'[c]' if flags else ''} {q(p)}", "atom"
        if flags:
            raise Skip("matches() with i flag and regex metacharacters")
        return f'{a} MATCHES {q("(?s:.*)(?-s:" + p + ")(?s:.*)")}', "atom"
    if f in ("true", "false"):
        raise Skip("true()/false() usage not supported")
    if f in ("position", "last"):
        raise Skip(f"{f}() in predicate")
    raise Skip(f"unsupported function {f}()")


def step_type(step):
    t = step["test"]
    if t == "*":
        return "*"
    r = real_type(t)
    if not r:
        raise Skip(f"{t} is not a real XCUITest type")
    return r


def desc_form(node):
    """node is ('path', ...) -> (T, inner_step) when .//T[p] or descendant::T[p]"""
    pth = node[1]
    st = pth["steps"]
    if len(st) != 1:
        raise Skip("multi-step path in predicate")
    s = st[0]
    ok = (pth["start"] == "." and s["sep"] == "//" and s["axis"] == "child") or \
         (pth["start"] is None and s["sep"] == "" and s["axis"] == "descendant")
    if not ok:
        raise Skip("child/other path test in predicate")
    return s


def step_parts(step, allow_desc=True):
    """-> (type, predstr|None, kind, descs)"""
    T0 = step_type(step)
    conj = []
    for p in step["preds"]:
        conj += flatten(p, "and")
    types = set()
    rendered = []
    descs = []
    for c in conj:
        if c[0] == "num":
            raise Skip("positional index inside step is per-parent, not global")
        if c[0] == "path":
            if not allow_desc:
                raise Skip("nested descendant test")
            descs.append(c)
            continue
        if is_true_drop(c):
            continue
        T = type_of(c)
        if T:
            types.add(T)
            continue
        rendered.append(render(c))
    if len(types) > 1:
        raise Skip("conflicting types")
    T = T0
    if types:
        (t1,) = types
        if T0 != "*" and T0 != t1:
            raise Skip("step type conflicts with @type test")
        T = t1
    if len(rendered) == 1:
        ps, kind = rendered[0]
    elif rendered:
        ps = " AND ".join(f"({s})" if k == "or" else s for s, k in rendered)
        kind = "and"
    else:
        ps, kind = None, "atom"
    dstrs = []
    for d in descs:
        if T == "*":
            raise Skip("descendant test needs a named outer type")
        s = desc_form(d)
        it = step_parts(s, allow_desc=False)
        if it[0] == "*":
            raise Skip("descendant test needs a named inner type")
        if it[0] == T:
            raise Skip("descendant test with the same type")
        inner = f'type == "{it[0]}"'
        if it[1]:
            inner += " AND " + (f"({it[1]})" if it[2] == "or" else it[1])
        dstrs.append(inner)
    return T, ps, kind, dstrs


def idx_value(n):
    if n[0] == "num" and re.fullmatch(r"\d+", n[1]):
        v = int(n[1])
        if v == 0:
            raise Skip("index 0")
        return v
    if n == ("fn", "last", []):
        return -1
    if n[0] == "arith" and n[1] == "-" and n[2] == ("fn", "last", []) and n[3][0] == "num" \
            and re.fullmatch(r"\d+", n[3][1]):
        return -(int(n[3][1]) + 1)
    if n[0] == "num":
        raise Skip("non-integer position")
    raise Skip("position is not a plain number / last()")


def render_step(step, idx=None):
    T, ps, kind, ds = step_parts(step)
    s = T
    if ps:
        s += f"[`{ps}`]"
    for d in ds:
        s += f"[${d}$]"
    if idx is not None:
        s += f"[{idx}]"
    return s


def convert_path(pth, idx):
    steps = pth["steps"]
    for s in steps:
        if s["axis"] == "ancestor" and s is steps[-1] and len(steps) == 2:
            continue
        if s["axis"] != "child":
            raise Skip(f"axis {s['axis']}:: not supported")
        if s["test"] in (".", ".."):
            raise Skip("self/parent step")
    # ancestor form
    if steps[-1]["axis"] == "ancestor":
        a, b = steps
        if idx is not None:
            raise Skip("index with ancestor")
        if pth["start"] != "abs" or a["sep"] != "//" or a["axis"] != "child" or b["preds"]:
            raise Skip("ancestor form not supported")
        T2 = step_type(b)
        T1 = step_type(a)
        if T1 == "*" or T2 == "*" or T1 == T2:
            raise Skip("ancestor needs two different named types")
        t, ps, kind, ds = step_parts(a, allow_desc=False)
        if t != T1 and t == "*":
            raise Skip("ancestor needs named types")
        inner = f'type == "{t}"'
        if ps:
            inner += " AND " + (f"({ps})" if kind == "or" else ps)
        if t == T2:
            raise Skip("same type")
        return f"**/{T2}[${inner}$]"
    lead = None
    if pth["start"] == "abs" and steps[0]["sep"] == "//":
        lead = "**/"
    elif pth["start"] == "abs":
        a = steps[0]
        if a["test"] != P + "Application" or a["preds"]:
            raise Skip("absolute path must start at XCUIElementTypeApplication")
        steps = steps[1:]
        if not steps:
            raise Skip("nothing below Application")
        lead = "**/" if steps[0]["sep"] == "//" else ""
    elif pth["start"] == ".":
        if steps[0]["sep"] != "//":
            raise Skip("relative child path")
        lead = "**/"
    else:
        raise Skip("relative path")
    if idx is not None and len(steps) != 1:
        raise Skip("index on multi-step path")
    out = lead
    for i, s in enumerate(steps):
        if i > 0:
            out += "/**/" if s["sep"] == "//" else "/"
        out += render_step(s, idx if i == len(steps) - 1 else None)
    return out


def convert_union(paths):
    branches = []
    for p in paths:
        st = p["steps"]
        if p["start"] != "abs" or len(st) != 1 or st[0]["sep"] != "//" or st[0]["axis"] != "child":
            raise Skip("union of non-simple paths")
        T, ps, kind, ds = step_parts(st[0], allow_desc=False)
        branches.append((T, ps, kind))
    types = {b[0] for b in branches}
    if len(types) == 1 and "*" not in types:
        (T,) = types
        if any(b[1] is None for b in branches):
            return f"**/{T}"
        strs = [f"({s})" if k == "and" else s for _, s, k in branches]
        return f"**/{T}[`{' OR '.join(strs)}`]"
    strs = []
    for T, ps, kind in branches:
        conj = []
        if T != "*":
            conj.append(f'type == "{T}"')
        if ps:
            conj.append(f"({ps})" if kind == "or" and conj else ps)
        if not conj:
            return "**/*"
        s = " AND ".join(conj)
        strs.append(f"({s})" if len(conj) > 1 or kind == "and" else s)
    return f"**/*[`{' OR '.join(strs)}`]"


def convert(xp):
    toks = tokenize(xp)
    top = Parser(toks).parse_top()
    if top[0] == "paths":
        paths, idxn = top[1], None
    else:
        paths, idxn = top[1], top[2]
    idx = idx_value(idxn) if idxn is not None else None
    if len(paths) > 1:
        if idxn is not None:
            raise Skip("index on union")
        chain = convert_union(paths)
    else:
        chain = convert_path(paths[0], idx)
    return "-ios class chain:" + chain


def main(inp, outp):
    data = json.load(open(inp))
    res = []
    for e in data:
        try:
            res.append({"id": e["id"], "chain": convert(e["xpath"])})
        except Skip as s:
            res.append({"id": e["id"], "skip": True, "reason": str(s)})
    json.dump(res, open(outp, "w"), ensure_ascii=False, indent=1)
    for e, r in zip(data, res):
        print(r["id"], e["xpath"][:150], "=>", r.get("chain") or "SKIP " + r["reason"])


main(sys.argv[1], sys.argv[2])
